import { Table, BooleanColumn, StringColumn, TranslatedTextColumn, BasicImageColumn } from '../../db'

export type sys_scope = typeof sys_scope
export const sys_scope = Table({
    name: 'sys_scope',
    extends: 'sys_package',
    schema: {
        can_edit_in_studio: BooleanColumn({ label: 'Can Edit Application in Studio', default: true }),
        //guided_setup_guid: referenceColumn({ referenceTable: gsw_content}),
        js_level: StringColumn({
            label: 'JavaScript Mode',
            default: 'es_latest',
            choices: {
                traditional: { label: 'traditional' },
                helsinki_es5: { label: 'helsinki_es5' },
                es_latest: { label: 'es_latest' },
            },
        }),
        //license: referenceColumn({ referenceTable: license_details }),
        logo: BasicImageColumn({}),
        private: BooleanColumn({ default: false }),
        restrict_table_access: BooleanColumn({ default: false }),
        runtime_access_tracking: StringColumn({
            choices: { permissive: { label: 'permissive' }, tracking: { label: 'tracking' } },
            dropdown: 'dropdown_with_none',
        }),
        scope: StringColumn({ maxLength: 18 }),
        scoped_administration: BooleanColumn({ label: 'Application administration', default: false }),
        short_description: TranslatedTextColumn({}),
        template: StringColumn({}),
        vendor: StringColumn({}),
        vendor_prefix: StringColumn({}),
    },
})
